      ],
      "residual_exposure": "Network failure during final email dispatch remains.",
      "evidence_src_ids": [
        "SRC-0013"
      ],
      "affects": [
        "3.1"
      ]
    },
    {
      "condition": "The system must keep all personal data in the United Kingdom under REQ-0008, while cloud configurations often route logs or telemetry overseas.",
      "event": "A third-party monitoring or diagnostic tool exports personal data or logs outside the United Kingdom.",
      "effect": "A breach of data residency requirements leads to contract termination and regulatory penalties.",
      "assumptions": [
        "The system is hosted in two data centers in the United Kingdom."
      ],
      "owner_role": "Technical lead",
      "trigger": "Cloud architecture review reveals traffic routed through an offshore management plane.",
      "responses": [
        "Audit all third-party dependencies and logging destinations.",
        "Pin all cloud resources to UK-based regions only."
      ],
      "residual_exposure": "Subcontractor updates changing routing configurations without notice.",
      "evidence_src_ids": [
        "SRC-0022"
      ],
      "affects": [
        "1.1"
      ]
    },
    {
      "condition": "The system must be live by 2027-06-30 under REQ-0012, with historic migration dependent on core records taking up to 30 combined high estimate days.",
      "event": "Delays in core record deployment push back historic migration and staff training beyond 2027-06-30.",
      "effect": "The project misses the contractual go-live deadline.",
      "assumptions": [
        "Historic spreadsheets can be successfully mapped to the standard record format."
      ],
      "owner_role": "Delivery lead",
      "trigger": "Work package 1.1 exceeds its low day estimate by more than 5 days.",
      "responses": [
        "Add engineering resources to parallelize migration scripts.",
        "De-scope non-essential historic records for post-go-live migration."
      ],
      "residual_exposure": "Data quality issues in spreadsheets causing manual data cleansing delays.",
      "evidence_src_ids": [
        "SRC-0026"
      ],
      "affects": [
        "1.1",
        "1.2",
        "2.1"
      ]
    }
  ],
  "open_questions": [
    {
      "text": "Does the 99% availability requirement in REQ-0010 exclude scheduled maintenance windows?",
      "src_ids": [
        "SRC-0024"
      ]
    },
    {
      "text": "Can the existing donor spreadsheet mentioned in REQ-0007 be accessed via automated scripts or is manual intervention required?",
      "src_ids": [
        "SRC-0021"
      ]
    }
  ]
}

